38	// stub rather than exercise for real in this file.
39	
40	vi.mock('@salesforce/retail-react-app/app/hooks/use-einstein', () => ({
41	  default: vi.fn(),
42	}));
43	
44	vi.mock('@salesforce/retail-react-app/app/hooks/use-datacloud', () => ({
