83	// ProductScroller is a real `forwardRef` component (product-scroller/index.jsx) — mocked as one
84	// too, rather than a plain function, so `<ProductScroller ref={ref} .../>` doesn't trip React's
85	// "function components cannot be given refs" warning for no reason.
86	vi.mock('@salesforce/retail-react-app/app/components/product-scroller', () => ({
87	  default: React.forwardRef(function ProductScrollerStub(_props: unknown, ref: React.Ref<HTMLDivElement>) {
88	    return <div ref={ref} data-testid="product-scroller-stub" />;
89	  }),
