110	// jsdom has no matchMedia implementation, and index.tsx's own `useBreakpointValue` call (the
111	// See-Full-History trigger threshold) calls it internally — a per-file polyfill, not a change
112	// to the frozen vitest.setup.ts (Tier 1), matching the identical, already-established precedent
113	// at drawer-menu/index.test.tsx (Chakra Drawer's own useBreakpointValue usage). `matches: false`
114	// unconditionally is what makes useBreakpointValue resolve to its `base` value in this
115	// environment — exactly what the See-Full-History tests below are written against.
116	beforeEach(() => {
117	  Object.defineProperty(window, 'matchMedia', {
118	    writable: true,
